<header class="an-head"><span>Administración</span><h1>Notificaciones dirigidas</h1><p>Envía información únicamente a las personas relacionadas.</p></header><?php if($adminNotificationsError):?><p class="an-error"><?=e($adminNotificationsError)?></p><?php endif;?><section class="an-stats"><article><strong><?=$adminNotifications['summary']['sent']?></strong><span>Envíos realizados</span></article><article><strong><?=$adminNotifications['summary']['recipients']?></strong><span>Notificaciones entregadas</span></article><article><strong><?=$adminNotifications['summary']['today']?></strong><span>Entregadas hoy</span></article></section><div class="an-grid"><section class="an-compose"><h2>Crear aviso</h2><form id="anForm"><input type="hidden" name="_csrf" value="<?=e($adminNotificationCsrf)?>"><label>Destinatarios<select name="scope"><option value="user">Una persona</option><option value="project">Personas de un proyecto</option><option value="role">Un rol</option><option value="all">Toda la plataforma</option></select></label><label data-scope="user">Usuario<select name="user_id"><option value="">Selecciona</option><?php foreach($adminNotifications['users'] as $u):?><option value="<?=$u['id']?>"><?=e($u['full_name'].' · '.$u['email'])?></option><?php endforeach;?></select></label><label data-scope="project" hidden>Proyecto<select name="project_id"><option value="">Selecciona</option><?php foreach($adminNotifications['projects'] as $p):?><option value="<?=$p['id']?>"><?=e($p['code'].' · '.$p['title'])?></option><?php endforeach;?></select></label><label data-scope="role" hidden>Rol<select name="role"><option value="student">Estudiantes</option><option value="teacher">Docentes</option><option value="administrator">Administradores</option></select></label><label>Tipo<select name="type"><option value="system">Comunicado del sistema</option><option value="reminder">Recordatorio</option><option value="status_change">Cambio de estado</option><option value="repository">Repositorio</option></select></label><label>Título<input name="title" maxlength="180" required></label><label>Mensaje<textarea name="message" maxlength="2000" required></textarea></label><label class="an-confirm" data-scope="all" hidden><input type="checkbox" name="confirm_all" value="1"><span>Confirmo que este comunicado institucional debe llegar a todos los usuarios activos.</span></label><p id="anMessage" hidden></p><button type="submit">Enviar notificación</button></form></section><section class="an-history"><h2>Actividad reciente</h2><?php if(!$adminNotifications['sent']):?><div class="an-empty">Aún no existen envíos administrativos.</div><?php else:foreach($adminNotifications['sent'] as $item):$details=json_decode((string)$item['details'],true)?:[];?><article><strong><?=e($details['title']??'Notificación')?></strong><p><?=e($item['sender']?:'Sistema')?> · <?=e($details['scope']??'dirigida')?></p><small><?=$details['recipients']??0?> destinatarios · <?=e(date('d/m/Y H:i',strtotime($item['created_at'])))?></small></article><?php endforeach;endif;?></section></div><div id="anConfig" data-endpoint="<?=e($adminNotificationSendEndpoint)?>"></div>
